import{z as i,x as B,o,c as p,q as s,j as E,D as r,d as e,s as d,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"线程局部存储","description":"","frontmatter":{"title":"线程局部存储","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/thread-tls.md","filePath":"cs/thread-tls.md","lastUpdated":1791063341000}'),A={name:"cs/thread-tls.md"};function T(c,a,S,h,m,L){const l=B("Mermaid");return o(),p("div",null,[a[2]||(a[2]=s('<h1 id="线程局部存储" tabindex="-1">线程局部存储 <a class="header-anchor" href="#线程局部存储" aria-label="Permalink to &quot;线程局部存储&quot;">​</a></h1><div class="epigraph"><p>同一符号在每个线程里对应不同的内存：栈是一份，TLS 把「看起来像全局量」的东西也变成每线程一份。</p><footer>—— 据 Drepper, ELF Handling For Thread-Local Storage；Silberschatz et al. 整理</footer></div><p><a href="/cs/ult-klt">上一课</a>把可调度对象钉成内核线程。共享地址空间里，全局变量默认<strong>所有线程看见同一份</strong>。<a href="/cs/thread-shared-addr">线程</a>已说栈与寄存器私有。缺口是：<code>errno</code>、运行时的当前对象、编译器的 <code>__thread</code> 变量既不是栈上的自动量，也不能放进真全局——那叫<strong>线程局部存储（TLS）</strong>。本课只钉模型，不写动态链接器的全部 TLS 模板。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 库把错误码放在 <code>errno</code>。若它是普通全局，两条线程的系统调用会互相覆盖错误。若每次数组按 tid 查找，又慢又要锁。硬件提供线程指针寄存器（或 <code>fs</code>/<code>tp</code>）：内核在切换时把它写成该线程 TLS 块的基址，用户用固定偏移访问。缺口不是新的 1:1 映射，而是这份<strong>每线程一块的数据段</strong>。</p><p><span class="marginnote">TLS 仍在该进程的页表里，只是每条线程的基址不同。别的线程若拿到指针，仍能读你的 TLS——私有是约定，不是硬件隔离。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>创建线程：分配 TLS 块，拷贝初始镜像（<code>.tdata</code>/<code>.tbss</code>），把硬件线程指针写入 PCB，切换时随寄存器恢复。静态 TLS 在加载时布局；动态加载的模块可能走慢路径分配。内核自己的 per-CPU 不是 TLS：一个是按 CPU，一个是按线程。</p>',8)),(o(),E(n,null,{default:r(()=>[d(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E7%BA%BF%E7%A8%8B1%20tp%22%5D%20--%3E%20B1%5B%22TLS%20%E5%9D%971%22%5D%0A%20%20T2%5B%22%E7%BA%BF%E7%A8%8B2%20tp%22%5D%20--%3E%20B2%5B%22TLS%20%E5%9D%972%22%5D%0A%20%20G%5B%22%E7%9C%9F%E5%85%A8%E5%B1%80%22%5D%20--%3E%20SHARE%5B%22%E4%B8%A4%E7%BA%BF%E7%A8%8B%E5%90%8C%E4%B8%80%E5%9C%B0%E5%9D%80%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"fork：POSIX 只保留调用线程，其 TLS 随地址空间复制语义走；其它线程的 TLS 丢掉。本课不展开 cow 细节。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,[e("TLS 让「看起来像全局」的 ABI 在多线程下仍正确。它不提供互斥：两个线程的 TLS 不相干，但指向同一堆对象的指针仍要锁。与"),t("a",{href:"/cs/context-switch"},"上下文切换"),e("的关系：漏存 "),t("code",null,"tp"),e(" 等于下一线程用错 errno 块。用户级线程库若在一条 KLT 上切 ULT，必须自己改 TLS 基址，否则库内「当前」会串。")],-1)),a[6]||(a[6]=t("p",null,[e("一条 "),t("code",null,"__thread"),e(" 变量的读访问为什么又快又不用锁：")],-1)),(o(),E(n,null,{default:r(()=>[d(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E8%AF%BB%20__thread%20%E5%8F%98%E9%87%8F%22%5D%20--%3E%20TP%5B%22%E5%8F%96%E7%A1%AC%E4%BB%B6%E7%BA%BF%E7%A8%8B%E6%8C%87%E9%92%88%20tp%22%5D%0A%20%20TP%20--%3E%20OFF%5B%22%E5%9C%B0%E5%9D%80%20%3D%20tp%20%2B%20%E5%9B%BA%E5%AE%9A%E5%81%8F%E7%A7%BB%22%5D%0A%20%20OFF%20--%3E%20LOAD%5B%22%E7%9B%B4%E6%8E%A5%E8%AE%BF%E5%AD%98%3A%20%E4%B8%8D%E6%9F%A5%E8%A1%A8%E4%B8%8D%E5%8A%A0%E9%94%81%22%5D%0A%20%20G%5B%22%E6%99%AE%E9%80%9A%E5%85%A8%E5%B1%80%E5%8F%98%E9%87%8F%22%5D%20--%3E%20RACE%5B%22%E4%B8%A4%E6%9D%A1%E7%BA%BF%E7%A8%8B%E5%90%8C%E4%B8%80%E5%9C%B0%E5%9D%80%22%5D%0A%20%20RACE%20--%3E%20LOCK%5B%22%E8%A6%81%E4%BA%92%E6%96%A5%2C%20%E8%BF%98%E4%BC%9A%E4%BA%92%E7%9B%B8%E8%A6%86%E7%9B%96%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">术语翻译：TLS 就是用「每线程一块内存、寄存器里放块基址」的手段，来做「同一个变量名、每线程各有一份值」的事。访问只需一次基址加偏移的加法，比按 tid 去数组里查快得多，也天然无锁。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Windows TEB 与 ELF TLS 的格式差异写完，不讨论如何用 TLS 做隐蔽存储。安全隔离不靠 TLS。也不把 GPU 的 private memory 混进来。</p><p>后课默认：每 KLT 有 TLS 基址。创建时哪些资源共享、哪些复制，Unix 用 <code>clone</code> 的位来选，下一课讲 clone 标志。</p><p><span class="marginnote">常见误区：初学者容易以为 TLS 变量对其他线程「不可见」——它仍在同一个地址空间里，别的线程拿到指针照样能读写。TLS 是访问约定的私有，不是硬件权限的隔离。</span></p><p><span class="marginnote">直觉类比：把 errno 想成每个工位自己的便签——系统调用失败时把错误号贴在自己工位上，各查各的便签，互不覆盖。若是公共白板，两条线程的错误码就会互相冲掉，后查的人看到的是别人的错误。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TLS：每线程一块数据，硬件线程指针指向它。</li><li>不是隔离：指针仍可跨线程传递。</li><li>共享哪些内核对象由 clone 标志决定，下一课。</li><li>出处：Drepper, <em>ELF TLS</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const _=i(A,[["render",T]]);export{u as __pageData,_ as default};
